pub fn imm_clamped(imm: i32) -> i32 {
    if (imm < IMM_MIN) {
        return IMM_MIN;
    }
    if (imm > IMM_MAX) {
        return IMM_MAX;
    }
    return imm;
}

pub fn imm_field(imm: i32) -> u32 {
    let mut c: i32 = imm_clamped(imm);
    if (c < 0) {
        return (((c + 65536) as u32) & IMM_MASK);
    }
    return ((c as u32) & IMM_MASK);
}

