pub fn t27a_encode(op: u32, dst: u32, s1: u32, s2: u32, v3: u32, imm: i32) -> u32 {
    let mut w: u32 = ((op & OPCODE_MASK) | ((dst & REG_MASK) << DST_SHIFT));
    if t27a_imm_form(op) {
        return ((w | ((s1 & SRC1_MASK_IMM_FORM) << SRC1_SHIFT)) | (imm_field(imm) << IMM_SHIFT));
    }
    w = (w | ((s1 & REG_MASK) << SRC1_SHIFT));
    if t27a_src2_form(op) {
        w = (w | ((s2 & REG_MASK) << SRC2_SHIFT));
    }
    if (op == OP_BUNDLE3) {
        w = (w | ((v3 & REG_MASK) << V3_SHIFT));
    }
    return w;
}

pub fn t27a_imm(w: u32, op: u32) -> i32 {
    if (t27a_imm_form(op) == false) {
        return 0;
    }
    let mut raw: u32 = ((w >> IMM_SHIFT) & IMM_MASK);
    if ((raw & IMM_SIGN_BIT) != 0) {
        return ((raw as i32) - 32768);
    }
    return (raw as i32);
}

pub fn t27a_imm_form(op: u32) -> bool {
    if (op == OP_SACR) {
        return true;
    }
    return has_imm(op);
}

pub fn t27a_src1(w: u32, op: u32) -> u32 {
    if t27a_imm_form(op) {
        return ((w >> SRC1_SHIFT) & SRC1_MASK_IMM_FORM);
    }
    return ((w >> SRC1_SHIFT) & REG_MASK);
}

pub fn t27a_src2(w: u32, op: u32) -> u32 {
    if t27a_src2_form(op) {
        return ((w >> SRC2_SHIFT) & REG_MASK);
    }
    return 0;
}

pub fn t27a_src2_form(op: u32) -> bool {
    if has_src2(op) {
        return true;
    }
    if (op == OP_DOT) {
        return true;
    }
    if (op == OP_BIND) {
        return true;
    }
    if (op == OP_BUNDLE2) {
        return true;
    }
    if (op == OP_BUNDLE3) {
        return true;
    }
    return false;
}

pub fn v3_of(word: u32, op: u32) -> u32 {
    if (op == OP_BUNDLE3) {
        return ((word >> V3_SHIFT) & REG_MASK);
    }
    return 0;
}

